cd /tmp/sv-39a01b06a9d94ade9de1feadbfdc4007/moderate-msbuild-properties && dotnet package list --format json > after-cpm-packages.json 2>&1 && python3 -c "
import json
b = json.load(open('baseline-packages.json'))
a = json.load(open('after-cpm-packages.json'))
def pkgs(data):
    result = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                result[(name, pkg['id'])] = pkg['resolvedVersion']
    return result
bp = pkgs(b); ap = pkgs(a)
if bp == ap: print('All packages resolve identically.')
else: print('DIFFERENCES:', set(bp.items()) ^ set(ap.items()))
